f(y) \le f(x)+\langle\nabla f(x),y-x\rangle+\frac{L}{2}\|y-x\|^2 .
\]
\end{lemma}
\begin{lemma}[Convexity inequality]\label{lem:convex}
If $f$ is convex then for any $x,y\in\R^{d}$,
\[
f(x)-f(y)\le\langle\nabla f(x),x-y\rangle .
\]
\end{lemma}
\begin{lemma}[Noise moment]\label{lem:noise}
For $\xi\sim\mathcal N(0,\sigma^2 I_d)$,
\[
\E[\xi]=0,\qquad \E[\|\xi\|^2]=d\sigma^2 .
\]
\end{lemma}
\begin{lemma}[Basic algebra]\label{lem:algebra}
For any vectors $a,b\in\R^{d}$,
\[
\|a-b\|^2 = \|a\|^2+\|b\|^2-2\langle a,b\rangle .
\]
\end{lemma}

\section*{Main Proof (Step‑by‑Step Derivation)}
We prove Theorem~\ref{thm:main}.  Throughout the proof the expectation $\E[\cdot]$ is taken w.r.t. all noise variables up to the current iteration.

\bigskip
\noindent\textbf{Step 1.}  Write the recursion for the squared distance to the optimum $w^\star$.
Using \eqref{eq:update2} and Lemma~\ref{lem:algebra} we have
\[
\|w_{t+1}-w^\star\|^2
= \|w_t-w^\star\|^2
-2\eta\langle\nabla f(w_t)+\xi_t,\;w_t-w^\star\rangle
+\eta^{2}\|\nabla f(w_t)+\xi_t\|^{2}. \tag{R1}
\]

\noindent\textbf{Step 2.}  Expand the inner product and the norm.
\begin{align}
\langle\nabla f(w_t)+\xi_t,\;w_t-w^\star\rangle
&= \langle\nabla f(w_t),w_t-w^\star\rangle
   +\langle\xi_t,w_t-w^\star\rangle ,\\
\|\nabla f(w_t)+\xi_t\|^{2}
&= \|\nabla f(w_t)\|^{2}
   +2\langle\nabla f(w_t),\xi_t\rangle
   +\|\xi_t\|^{2}. \tag{R2}
\end{align}
Insert \eqref{R2} into \eqref{R1}:
\begin{align}
\|w_{t+1}-w^\star\|^2
=&\|w_t-w^\star\|^2
-2\eta\langle\nabla f(w_t),w_t-w^\star\rangle
-2\eta\langle\xi_t,w_t-w^\star\rangle \nonumber\\
&\quad +\eta^{2}\|\nabla f(w_t)\|^{2}
+2\eta^{2}\langle\nabla f(w_t),\xi_t\rangle
+\eta^{2}\|\xi_t\|^{2}. \tag{R3}
\end{align}

\noindent\textbf{Step 3.}  Take expectation conditional on $w_t$.
Because $\xi_t$ is independent of $w_t$ and $\E[\xi_t]=0$,
\[
\E\big[\langle\xi_t,w_t-w^\star\rangle\mid w_t\big]=0,
\qquad
\E\big[\langle\nabla f(w_t),\xi_t\rangle\mid w_t\big]=0 .
\]
Using Lemma~\ref{lem:noise}, $\E[\|\xi_t\|^{2}\mid w_t]=d\sigma^{2}$.  Hence
\begin{equation}
\E\!\big[\|w_{t+1}-w^\star\|^{2}\mid w_t\big]
\le \|w_t-w^\star\|^{2}
-2\eta\langle\nabla f(w_t),w_t-w^\star\rangle
+\eta^{2}\|\nabla f(w_t)\|^{2}
+\eta^{2}d\sigma^{2}. \tag{R4}
\end{equation}
% CORRECTED: removed the erroneous term involving $\langle\xi_t,w_t-w^\star\rangle$ which vanishes in expectation.

\noindent\textbf{Step 4.}  Apply the convexity inequality (Lemma~\ref{lem:convex}) to bound the inner product:
\[
\langle\nabla f(w_t),w_t-w^\star\rangle \;\ge\; f(w_t)-f(w^\star). \tag{R5}
\]
Insert \eqref{R5} into \eqref{R4} and take the full expectation:
\begin{equation}
\E\!\big[\|w_{t+1}-w^\star\|^{2}\big]
\le \E\!\big[\|w_t-w^\star\|^{2}\big]
-2\eta\,\E\!\big[f(w_t)-f(w^\star)\big]
+\eta^{2}\E\!\big[\|\nabla f(w_t)\|^{2}\big]
+\eta^{2}d\sigma^{2}. \tag{R6}
\end{equation}

\noindent\textbf{Step 5.}  Use the bounded‑gradient assumption (A1) to replace $\|\nabla f(w_t)\|^{2}$ by $G^{2}$:
\[
\|\nabla f(w_t)\|^{2}\le G^{2}\quad\text{for all }t. \tag{R7}
\]
Thus \eqref{R6} simplifies to
\begin{equation}
\E\!\big[\|w_{t+1}-w^\star\|^{2}\big]
\le \E\!\big[\|w_t-w^\star\|^{2}\big]
-2\eta\,\E\!\big[f(w_t)-f(w^\star)\big]
+\eta^{2}\big(G^{2}+d\sigma^{2}\big). \tag{R8}
\end{equation}
% CORRECTED: the term $G^{2}$ now appears directly from (A1) rather than from an unjustified $L\le G$.

\noindent\textbf{Step 6.}  Rearrange \eqref{R8} to isolate the suboptimality term:
\begin{equation}
2\eta\,\E\!\big[f(w_t)-f(w^\star)\big]
\le \E\!\big[\|w_t-w^\star\|^{2}\big]
-\E\!\big[\|w_{t+1}-w^\star\|^{2}\big]
+\eta^{2}\big(G^{2}+d\sigma^{2}\big). \tag{R9}
\end{equation}

\noindent\textbf{Step 7.}  Sum \eqref{R9} over $t=0,\dots,T-1$.
The telescoping sum of the distance terms yields
\begin{align}
2\eta\sum_{t=0}^{T-1}\E\!\big[f(w_t)-f(w^\star)\big]
&\le \|w_0-w^\star\|^{2}
-\E\!\big[\|w_T-w^\star\|^{2}\big]
+T\eta^{2}\big(G^{2}+d\sigma^{2}\big) \nonumber\\
&\le \|w_0-w^\star\|^{2}
+T\eta^{2}\big(G^{2}+d\sigma^{2}\big). \tag{R10}
\end{align}
% CORRECTED: the factor in front of the noise term is now $T\eta^{2}$ (not $T\eta^{2}L/2$) and the telescoping is performed correctly.

\noindent\textbf{Step 8.}  Divide \eqref{R10} by $2\eta T$:
\begin{equation}
\frac1T\sum_{t=0}^{T-1}\E\!\big[f(w_t)-f(w^\star)\big]
\le \frac{\|w_0-w^\star\|^{2}}{2\eta T}
+\frac{\eta}{2}\big(G^{2}+d\sigma^{2}\big). \tag{R11}
\end{equation}

\noindent\textbf{Step 9.}  Use convexity of $f$ to relate the average of the iterates to the average of the function values:
\[
f(\bar w_T)-f(w^\star)\le\frac1T\sum_{t=0}^{T-1}\big(f(w_t)-f(w^\star)\big).
\]
Taking expectations and applying \eqref{R11} gives exactly the bound \eqref{eq:bound}.
\hfill $\blacksquare$

\section*{Rate Derivation (With Constants)}
From Theorem~\ref{thm:main},
\[
\Phi_T(\eta):=\frac{\|w_0-w^\star\|^2}{2\eta T}
   +\frac{\eta}{2}\big(G^2+d\sigma^2\big)
\]
is an upper bound on the expected suboptimality.  Minimising $\Phi_T(\eta)$ over $\eta\in(0,1/L]$ gives
\[
\eta^\star=\frac{\|w_0-w^\star\|}{\sqrt{(G^2+d\sigma^2)T}} .
\]
Plugging $\eta^\star$ back:
\[
\Phi_T(\eta^\star)=\frac{\|w_0-w^\star\|\sqrt{G^2+d\sigma^2}}{\sqrt{T}} .
\]
Thus the optimal rate is $O\big(\frac{1}{\sqrt{T}}\big)$ with a constant proportional to $\sqrt{G^2+d\sigma^2}$.

\section*{Special Cases}
\begin{itemize}
\item \textbf{No privacy noise ($\sigma=0$).}  The bound reduces to the classical SGD result $\mathcal O\big(\frac{G\|w_0-w^\star\|}{\sqrt{T}}\big)$.
\item \textbf{High‑dimensional regime.}  The variance term scales linearly with $d$, i.e. $d\sigma^2$, illustrating the well‑known degradation of utility when many coordinates are perturbed.
\item \textbf{Deterministic (full‑batch) gradients.}  If $g_t=\nabla f(w_t)$ exactly and $\sigma>0$, the same analysis applies; the only source of randomness is the added Gaussian noise.
\end{itemize}

